import { writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const gap = 'var(--sf-mosaic-gap, 0.95rem)'
/** Percent mosaic targets (max-width OK — not outline boxed containers). */
const mosaicSels = [
  '.sf-grid-col',
  '.admin-shell .gantry-sections > .gantry-section',
  '.sf-profile-form-mosaic > .settings-fieldset',
]

/** Public layout sections in a mosaic row — flex/width only; boxed owns max-width. */
const publicSectionMosaic = '.sf-layout-section-mosaic > .sf-layout-section'

const lines = [
  '/* Generated by scripts/gen-grid-widths.mjs — mosaic/column widths via data-sf-width.',
  ' * Do not set flex/width/max-width inline on these elements.',
  ' * Boxed sections: max-width = outline --sf-container-max (large-desktop breakpoint).',
  ' */',
  '',
  '/* Full-width public sections: never set max-width here — container mode + breakpoints. */',
  '.sf-layout-section[data-sf-width="100"],',
  '.sf-layout-section:not([data-sf-width]),',
  `${publicSectionMosaic}[data-sf-width="100"] {`,
  '  flex: 0 0 100%;',
  '  width: 100%;',
  '  min-width: 0;',
  '  box-sizing: border-box;',
  '}',
  '',
]

for (const sel of mosaicSels) {
  lines.push(
    `${sel}[data-sf-width="100"] {`,
    '  flex: 0 0 100%;',
    '  width: 100%;',
    '  max-width: 100%;',
    '  min-width: 0;',
    '  box-sizing: border-box;',
    '}',
    '',
  )
}

for (let n = 5; n <= 99; n++) {
  const basis = `calc(${n}% - ${gap})`
  const sel = [...mosaicSels, publicSectionMosaic]
    .map((s) => `${s}[data-sf-width="${n}"]`)
    .join(',\n')
  lines.push(
    `${sel} {`,
    `  flex: 0 0 ${basis};`,
    `  width: ${basis};`,
    `  max-width: ${basis};`,
    '  min-width: 0;',
    '  box-sizing: border-box;',
    '}',
    '',
  )
}

const outPath = join(dirname(fileURLToPath(import.meta.url)), '..', 'src', 'core', 'modules', 'grid-widths.css')
writeFileSync(outPath, lines.join('\n'), 'utf8')
console.log(`Wrote ${outPath} (${lines.length} lines)`)
